require_once __DIR__.'/../includes/admin-functions.php';
$schema=dental_schema($pdo);
$labId=$schema->labId();$serviceId=$schema->serviceId();$imageId=$schema->imageId();$imagePath=$schema->imagePath();
$hasLabDate=$schema->hasCreatedAt();$hasImageDate=$schema->hasCreatedAt('image_laboratoire');
$pending=$schema->status('en_attente');$valid=$schema->status('valide');$rejected=$schema->status('rejete');
$counts=['total'=>(int)$pdo->query('SELECT COUNT(*) FROM laboratoire')->fetchColumn()];
foreach(['en_attente'=>$pending,'valide'=>$valid,'rejete'=>$rejected] as $key=>$status){$q=$pdo->prepare('SELECT COUNT(*) FROM laboratoire WHERE statut=?');$q->execute([$status]);$counts[$key]=(int)$q->fetchColumn();}
$counts['services']=(int)$pdo->query('SELECT COUNT(*) FROM service')->fetchColumn();$counts['photos']=(int)$pdo->query('SELECT COUNT(*) FROM image_laboratoire')->fetchColumn();
$counts['new_month']=$hasLabDate?(int)$pdo->query("SELECT COUNT(*) FROM laboratoire WHERE created_at>=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')")->fetchColumn():0;
$recentDate=$hasLabDate?'l.created_at':'NULL';$sortRecent=$hasLabDate?'l.created_at DESC,':' ';$imageSort=$hasImageDate?'i.created_at DESC,':'';
$sql="SELECT l.`$labId` id,l.nom_laboratoire,l.nom_gerant,l.email,l.ville,l.statut,$recentDate created_at,(SELECT i.`$imagePath` FROM image_laboratoire i WHERE i.laboratoire_id=l.`$labId` ORDER BY $imageSort i.`$imageId` LIMIT 1) photo FROM laboratoire l ORDER BY $sortRecent l.`$labId` DESC LIMIT 8";
$recent=$pdo->query($sql)->fetchAll();
$rows=$hasLabDate?$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') m,COUNT(*) n FROM laboratoire WHERE created_at>=DATE_SUB(CURRENT_DATE,INTERVAL 5 MONTH) GROUP BY m ORDER BY m")->fetchAll():[];
$map=[];foreach($rows as $r)$map[$r['m']]=(int)$r['n'];$chart=[];
for($i=5;$i>=0;$i--){$k=date('Y-m',strtotime("first day of -$i month"));$chart[]=['label'=>date('M',strtotime($k.'-01')),'n'=>$map[$k]??0];}
$max=max(1,...array_column($chart,'n'));$total=max(1,$counts['total']);
$adminPendingCount=$counts['en_attente'];$validPct=(int)round($counts['valide']/$total*100);$pendingPct=(int)round($counts['en_attente']/$total*100);$rejectedPct=max(0,100-$validPct-$pendingPct);
$validEnd=$validPct;$pendingEnd=$validPct+$pendingPct;
$points=[];$chartMax=max(1,...array_column($chart,'n'));
foreach($chart as $i=>$bar){$x=48+$i*($i===5?0:0);$x=48+$i*148;$y=205-(($bar['n']/$chartMax)*145);$points[]=['x'=>$x,'y'=>$y,'label'=>$bar['label'],'n'=>$bar['n']];}
$linePoints=implode(' ',array_map(static fn($p)=>$p['x'].','.$p['y'],$points));
$areaPoints='48,205 '.$linePoints.' 788,205';
